using namespace fathom;using namespace fathom::tasks::manual_procedure_graph;using namespace fathom::tests::manual_procedure_fixture;
namespace {std::size_t assertions{},refusals{};void require(bool b,const char* w){++assertions;check(b,w);}std::string action(const ManualProcedureGraph& t){return f(t.learnerActions().array().front(),"action").string();}void advance(ManualProcedureGraph& t){t.apply(t.capture(action(t)),positiveFor(t));}void at(ManualProcedureGraph& t,const std::string& node){for(int i=0;i<100;++i){auto v=t.learnerView();if(f(v,"state")==V("active")&&f(v,"node")==V(node))return;advance(t);}throw std::runtime_error("NODE");}void finish(ManualProcedureGraph& t){for(int i=0;i<100&&f(t.learnerView(),"state")!=V("completed");++i)advance(t);require(f(t.learnerView(),"state")==V("completed"),"FINISH");}std::string find(const std::string& program,const std::string& text=""){for(const auto& k:keys()){const auto& p=definition(k).retainedProgram();if(f(p,"name")==V(program)&&(text.empty()||json::stringify(p).find(text)!=std::string::npos))return k;}throw std::runtime_error("EXACT_PROGRAM");}void refuse(ManualProcedureGraph& t,const V& input){const auto token=t.capture(action(t));const auto v=t.learnerView();auto h=t.history();try{t.apply(token,input);require(false,"MALFORMED_REFUSE");}catch(const tasks::recipes::Error&){++refusals;require(v==t.learnerView()&&h==t.history()&&t.current(token),"MALFORMED_UNCHANGED");}}}
