 // Maximum fill is a ceiling; zero remains a valid chosen no-fill realization.
 for(int count:{0,2,3}){ManualProcedureGraph t(definition(find("released_c_89_fill_window","beat 4")));at(t,"stage_01");auto p=positiveFor(t);p.object()["reported_fill_contact_count"]=V::fromInteger(count);t.apply(t.capture("submit"),p);advance(t);require(f(t.learnerView(),"state")==V(count>2?"needs_retry":"completed"),"FILL_CEILING_NO_MINIMUM");}
 {ManualProcedureGraph t(definition(find("released_c_89_fill_window_rest")));at(t,"stage_01");require(f(f(t.retainedDefinition().retainedProgram(),"graph"),"nodes").object().at("stage_01").find("physical")->boolean()==false,"NO_WINDOW_NO_FABRICATED_ACTIVITY");t.apply(t.capture("submit"),positiveFor(t));require(f(t.learnerView(),"state")==V("completed")&&f(t.learnerView(),"needs_manual_release")==V(false),"REST_COMPLETES_WITHOUT_PHYSICAL_RELEASE");}
