 for(const char* choice:{"fifth_omitted_after_instability","upper_structure_moved_nearer_after_instability"}){ManualProcedureGraph t(definition(find("released_c_81_voicing_contact_spread_drop_3")));at(t,"stage_02");auto p=positiveFor(t);p.object()["actual_comfort_response"]=choice;t.apply(t.capture("submit"),p);advance(t);require(f(t.learnerView(),"state")==V("completed"),"SPREAD_RECOVERY_ALLOWED");}
 // A copied definition keeps its exact original/context value after the local
